//! `Text::from_ansi` compared with Python Rich 15's `Text.from_ansi`,
//! using `tests/fixtures/ansi_decode.golden` (generated by
//! `scripts/gen_ansi_golden.py`): plain text and the style of every
//! character. Also checks that fast-rich's own console output decodes back
//! to the spans it was rendered from.

use fast_rich::console::{ColorSystem, Console};
use fast_rich::style::{Color, Style};
use fast_rich::text::{Span, Text};

const GOLDEN: &str = include_str!("fixtures/ansi_decode.golden");

fn unhex(hex: &str) -> String {
    let bytes: Vec<u8> = (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect();
    String::from_utf8(bytes).unwrap()
}

fn color_desc(color: Color) -> String {
    let named = [
        Color::Black,
        Color::Red,
        Color::Green,
        Color::Yellow,
        Color::Blue,
        Color::Magenta,
        Color::Cyan,
        Color::White,
        Color::BrightBlack,
        Color::BrightRed,
        Color::BrightGreen,
        Color::BrightYellow,
        Color::BrightBlue,
        Color::BrightMagenta,
        Color::BrightCyan,
        Color::BrightWhite,
    ];
    match color {
        Color::Default => "default".into(),
        Color::Ansi256(n) => n.to_string(),
        Color::Rgb { r, g, b } => format!("#{r:02x}{g:02x}{b:02x}"),
        named_color => named
            .iter()
            .position(|c| *c == named_color)
            .unwrap()
            .to_string(),
    }
}

/// The golden's style description: attributes (Rich order), fg, bg, link.
fn style_desc(style: &Style, link: Option<&str>) -> String {
    let mut words: Vec<String> = Vec::new();
    let attrs = style.to_string();
    if !attrs.is_empty() {
        words.push(attrs);
    }
    if let Some(c) = style.foreground {
        words.push(format!("fg={}", color_desc(c)));
    }
    if let Some(c) = style.background {
        words.push(format!("bg={}", color_desc(c)));
    }
    if let Some(url) = link {
        words.push(format!("link={url}"));
    }
    words.join(" ")
}

/// Runs of `(chars, description)` over the text's characters.
fn runs(text: &Text) -> Vec<(usize, String)> {
    let mut out: Vec<(usize, String)> = Vec::new();
    for span in &text.spans {
        let desc = style_desc(&span.style, span.link.as_deref());
        let n = span.text.chars().count();
        if n == 0 {
            continue;
        }
        match out.last_mut() {
            Some(last) if last.1 == desc => last.0 += n,
            _ => out.push((n, desc)),
        }
    }
    out
}

#[test]
fn from_ansi_matches_rich() {
    let mut count = 0;
    let mut failures = Vec::new();
    for line in GOLDEN.lines().filter(|l| !l.starts_with("# ")) {
        let f: Vec<&str> = line.split(' ').collect();
        let input = unhex(f[0]);
        let want_plain = unhex(f[1]);
        let want_runs: Vec<(usize, String)> = if f[2] == "-" {
            Vec::new()
        } else {
            f[2].split(',')
                .map(|run| {
                    let (n, d) = run.split_once(':').unwrap();
                    (n.parse().unwrap(), unhex(d))
                })
                .collect()
        };
        let text = Text::from_ansi(&input);
        let plain = text.plain_text();
        if plain != want_plain {
            failures.push(format!("{input:?}: plain {plain:?} != rich {want_plain:?}"));
        } else if runs(&text) != want_runs {
            failures.push(format!(
                "{input:?}: styles {:?} != rich {want_runs:?}",
                runs(&text)
            ));
        }
        count += 1;
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    assert_eq!(count, 210);
}

/// Neighbouring spans with the same style and link merged, empty ones
/// dropped.
fn normalized(spans: &[Span]) -> Vec<(String, Style, Option<String>)> {
    let mut out: Vec<(String, Style, Option<String>)> = Vec::new();
    for span in spans.iter().filter(|s| !s.text.is_empty()) {
        match out.last_mut() {
            Some(last) if last.1 == span.style && last.2 == span.link => {
                last.0.push_str(&span.text)
            }
            _ => out.push((span.text.to_string(), span.style, span.link.clone())),
        }
    }
    out
}

fn render(text: &Text, system: ColorSystem) -> String {
    let console = Console::capture()
        .width(500)
        .force_color(true)
        .color_system(system);
    console.print_renderable(text);
    console.get_captured_output()
}

#[test]
fn round_trip_of_fast_rich_output() {
    let styles = [
        Style::new(),
        Style::parse("bold red"),
        Style::parse("dim italic on blue"),
        Style::parse("underline #ff8000 on #102030"),
        Style::parse("blink blink2 reverse conceal strike"),
        Style::parse("underline2 frame encircle overline"),
        Style::parse("bright_cyan on grey23"),
        Style::parse("color(200) on color(17)"),
        Style::parse("bold dim italic underline blink blink2 reverse conceal strike underline2 frame encircle overline green on white"),
    ];
    let words = ["alpha", " ", "日本語", "x", "😀 ok", "-->"];
    let mut spans = Vec::new();
    for (i, style) in styles.iter().cycle().take(40).enumerate() {
        let word = words[i % words.len()];
        if i % 7 == 3 {
            spans.push(Span::linked(
                word,
                *style,
                format!("https://example.com/{i}"),
            ));
        } else {
            spans.push(Span::styled(word, *style));
        }
    }
    // `no_wrap`: render the spans as they are (wrapping re-splits words).
    let text = Text::from_spans(spans.clone()).no_wrap();
    let decoded = Text::from_ansi(&render(&text, ColorSystem::TrueColor));
    let mut want = normalized(&spans);
    // The console ends the line with a newline.
    want.push(("\n".into(), Style::new(), None));
    assert_eq!(normalized(&decoded.spans), want);

    // 256-color output decodes to the palette colors it was written with.
    let decoded = Text::from_ansi(&render(
        &Text::styled("x", Style::parse("color(196) on color(17)")),
        ColorSystem::EightBit,
    ));
    assert_eq!(decoded.spans[0].style.foreground, Some(Color::Ansi256(196)));
    assert_eq!(decoded.spans[0].style.background, Some(Color::Ansi256(17)));
}

#[test]
fn decoded_text_has_visible_width() {
    let text = Text::from_ansi("\x1b[1;31merror\x1b[0m: \x1b]8;;https://x\x1b\\here\x1b]8;;\x1b\\");
    assert_eq!(text.width(), "error: here".len());
}
